<div class="erp-page-head"><form class="erp-filter" method="get"><input class="form-control form-control-sm" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="No. transaksi">
    <select class="form-select form-select-sm" name="status"><option value="">Semua</option><?php foreach (['DRAFT', 'PAID', 'VOID'] as $st): ?><option <?= ($_GET['status'] ?? '') === $st ? 'selected' : '' ?>><?= $st ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-secondary">Filter</button></form>
    <?php if (can('sales.pos.create')): ?><a class="btn btn-sm btn-primary" href="<?= site_url('sales/pos/create') ?>" data-testid="pos-create-btn"><i class="bi bi-cart-plus me-1"></i>Transaksi Baru</a><?php endif; ?></div>
<div class="card erp-card"><table class="table table-sm table-hover erp-table mb-0" data-testid="pos-table"><thead><tr><th>No.</th><th>Waktu</th><th>Pelanggan</th><th>Kasir</th><th class="text-end">Total</th><th class="text-end">Bayar</th><th>Status</th></tr></thead><tbody>
<?php foreach ($page->items as $s): ?><tr data-testid="pos-row-<?= $s['id'] ?>"><td class="font-monospace small"><a href="<?= site_url('sales/pos/' . $s['id']) ?>"><?= e($s['sale_no']) ?></a></td><td class="small"><?= fmt_dt($s['sale_datetime']) ?></td><td class="small"><?= e($s['customer_name'] ?: 'Umum') ?></td><td class="small"><?= e($s['cashier_name']) ?></td><td class="text-end"><?= fmt_idr($s['grand_total']) ?></td><td class="text-end small"><?= fmt_idr($s['paid_total']) ?></td><td><?= status_badge($s['status']) ?></td></tr><?php endforeach; ?>
<?php if (!$page->items): ?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada transaksi</td></tr><?php endif; ?></tbody></table><div class="card-footer py-1"><?php $this->load->view('partials/pagination', ['page' => $page]); ?></div></div>
